    Object.assign(n(A),{label:'Idee',status:'De făcut',keywords:['fir-a'],sectionType:'Scenă',target:100,created:'2024-02-02T12:00:00Z',modified:'2024-02-02T12:00:00Z',custom:{Data:'2024-02-02',Ora:'12:00',Durata:'2h',POV:'Ana',Loc:'Castel',Număr:'2'}});
    Object.assign(n(B),{label:'Loc',status:'Final',keywords:['fir-b'],includeInCompile:false,sectionType:'Capitol',target:200,created:'2024-01-01T12:00:00Z',modified:'2024-01-01T12:00:00Z',custom:{Data:'2024-01-01',Ora:'09:00',Durata:'30 min',POV:'Ion',Loc:'Port',Număr:'10'}});
    files['docs/doc-a.html']='<p>Ana și Ion merg.</p><p>„Vino acum”, spune Ana.</p>';
