  const columns=[['synopsis','Sinopsis'],['label','Etichetă'],['status','Status'],['keywords','Cuvinte cheie'],['sectionType','Tip secțiune'],['include','În Compile'],['words','Cuvinte'],['total','Total cuvinte'],['chars','Caractere'],['target','Țintă'],['progress','Progres'],['created','Creat'],['modified','Modificat'],['custom:Data','Data'],['custom:Ora','Ora'],['custom:Durata','Durata'],['custom:POV','POV'],['custom:Loc','Loc'],['custom:Număr','Număr']];
  const showColumn=async key=>{const col=columns.find(x=>x[0]===key);const details=outline().locator('.col-chooser');if(await details.getAttribute('open')===null)await details.locator('summary').click();await details.locator('label').filter({hasText:new RegExp('^\\s*'+col[1]+'\\s*$')}).locator('input').check();};
  const colCell=(id,key)=>row(id).locator('td').nth(1); // used with only one displayed column
  const onlyColumn=async key=>{await p().evaluate(key=>localStorage.setItem('pneuma-outline-columns',JSON.stringify([key])),key);await H.command('viewEditor');await H.command('viewOutline');await visible(outline());};
  const fillBlur=async(loc,value)=>{await loc.fill(String(value));await loc.press('Tab');};
