  for(const key of ['Enter','F2'])for(const outcome of ['commit','cancel','blank'])
    T('cork-title-'+key+'-'+outcome,'Corkboard','Fișă / titlu '+key+' '+outcome,'Enter salvează titlul valid; Escape și titlul gol păstrează originalul; focusul revine la fișă.',async()=>view('cork'),async()=>{await card(A).focus();await card(A).press(key);const input=card(A).locator('header input');await input.fill(outcome==='blank'?'   ':'Titlu din panou');await input.press(outcome==='cancel'?'Escape':'Enter');},async()=>{await H.save();await H.wait(()=>H.node(A).title===(outcome==='commit'?'Titlu din panou':'Capitol verificat'));await focusIs(`[data-card-id="${A}"]`);});
  T('cork-synopsis','Corkboard','Fișă / sinopsis','Textul editat este salvat în project.json fără alterarea HTML-ului documentului.',async()=>view('cork'),async()=>fillBlur(card(A).locator('textarea'),'Sinopsis nou verificat'),async()=>{await persisted(A,'synopsis','Sinopsis nou verificat');H.assert(H.doc(A).includes('Prima frază'),'Body changed by synopsis');});
  for(const method of ['button','header-double','body-double','ctrl-enter'])
    T('cork-open-'+method,'Corkboard','Fișă / deschide '+method,'Documentul corect, titlul, conținutul și focusul editorului; Înapoi revine la dosar.',async()=>view('cork'),async()=>{if(method==='button')await card(B).getByRole('button',{name:'Deschide',exact:true}).click();else if(method==='header-double')await card(B).locator('.card-title').dblclick();else if(method==='body-double')await card(B).dblclick({position:{x:2,y:45}});else{await card(B).focus();await card(B).press('Control+Enter');}},async()=>{await current(B,'Text separat');await focusIs('.workspace .ProseMirror');await H.command('back');await H.wait(async()=> (await main().locator('.scriv-head').innerText()).includes('Dosar verificat'));},['back']);
  for(const key of ['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'])
    T('cork-nav-'+key,'Corkboard','Fișe / tastatură '+key,'Fișa vecină este selectată și focalizată fără a schimba documentul Binder.',async()=>{await H.fixture(async(project)=>{H.flat(project.tree).find(n=>n.id===F).cork={columns:1};});await view('cork');},async()=>{const from=['ArrowLeft','ArrowUp','Home'].includes(key)?B:A;await card(from).focus();await card(from).press(key);},async()=>{const target=['ArrowLeft','ArrowUp','Home'].includes(key)?A:B;await focusIs(`[data-card-id="${target}"]`);H.assert(await card(target).getAttribute('aria-selected')==='true','Neighbour not selected');H.assert(await H.row(F).getAttribute('aria-selected')==='true','Card navigation changed Binder selection');});
  for(const [key,from]of [['Control+ArrowRight',A],['Control+ArrowLeft',B]])
    T('cork-reorder-'+(from===A?'right':'left'),'Corkboard','Fișă / '+key,'Ordinea doc-b/doc-a este salvată; ID și HTML neschimbate, focus păstrat.',async()=>view('cork'),async()=>{await card(from).focus();await card(from).press(key);},async()=>{await H.save();await H.wait(()=>equal(H.node(F).children.map(n=>n.id),[B,A]));H.assert(equal(await ids(board().locator('[data-card-id]')),[B,A]),'Visual order differs');await focusIs(`[data-card-id="${from}"]`);H.assert(H.doc(A).includes('Prima frază'),'Body lost');});
  T('cork-add-after','Corkboard','+ Fișă','Fișa nouă este inserată după selecția locală, redenumită și are fișier HTML propriu.',async()=>view('cork'),async()=>{await card(A).focus();await board().getByRole('button',{name:'+ Fișă',exact:true}).click();await board().locator('header input').fill('Fișa creată');await board().locator('header input').press('Enter');},async()=>{await H.save();await H.wait(()=>H.node(F).children.length===3);const list=H.node(F).children;H.assert(list[1].title==='Fișa creată'&&list[2].id===B,'New card not inserted after selected');H.assert(H.fs.existsSync(H.dir+'/docs/'+list[1].id+'.html'),'New HTML missing');});
  T('cork-empty-add','Corkboard','Panou gol / + Fișă','Starea goală este explicată și primul document se creează în containerul gol.',async()=>{await H.fixture(async pj=>{H.flat(pj.tree).find(n=>n.id===F).children=[];});await view('cork');},async()=>{await H.wait(async()=> (await board().innerText()).includes('Nicio fișă'));await board().getByRole('button',{name:'+ Fișă',exact:true}).click();await board().locator('header input').fill('Prima fișă');await board().locator('header input').press('Enter');},async()=>{await H.save();await H.wait(()=>H.node(F).children.length===1);H.assert(H.node(F).children[0].title==='Prima fișă','Wrong empty-board insertion');});
  for(const mode of ['grid','lines'])for(const side of ['before','after'])
    T('cork-drag-'+mode+'-'+side,'Corkboard','Drag fișă '+mode+' '+side,'Ordinea este mutată în project.json și renderer; linii preiau metadata rândului țintă.',async()=>{await planFixture();await view('cork');if(mode==='lines')await board().getByRole('button',{name:'Linii',exact:true}).click();},async()=>drag(card(side==='after'?A:B),card(side==='after'?B:A),'x',side==='after'?.9:.1),async()=>{await H.save();await H.wait(()=>equal(H.node(F).children.map(n=>n.id),[B,A]));if(mode==='lines')H.assert(H.node(side==='after'?A:B).label===(side==='after'?'Loc':'Idee'),'Line drop did not adopt label');H.assert(H.doc(B).includes('Ion'),'Body lost on move');});
  T('cork-free-move','Corkboard','Liber / mută fișă','Coordonatele pixelilor persistă și coincid cu poziția CSS.',async()=>{await view('cork');await board().getByRole('button',{name:'Liber',exact:true}).click();},async()=>{const r=await card(A).locator('.card-title').boundingBox();await p().mouse.move(r.x+5,r.y+5);await p().mouse.down();await p().mouse.move(r.x+70,r.y+55,{steps:8});await p().mouse.up();},async()=>{await H.save();await H.wait(()=>Boolean(H.node(A).corkPos));const pos=H.node(A).corkPos;H.assert(pos.x>20&&pos.y>20,'Freeform card not moved');H.assert(await card(A).evaluate((e,pos)=>e.style.left===pos.x+'px'&&e.style.top===pos.y+'px',pos),'Saved coordinates differ');});
  T('cork-free-commit','Corkboard','Liber / Fixează ordinea','Ordinea vizuală doc-b/doc-a este scrisă în arbore fără schimbarea conținutului.',async()=>{await H.fixture(async pj=>{const n=id=>H.flat(pj.tree).find(x=>x.id===id);n(F).cork={mode:'free'};n(A).corkPos={x:350,y:100};n(B).corkPos={x:20,y:20};});await view('cork');},async()=>board().getByRole('button',{name:'Fixează ordinea',exact:true}).click(),async()=>{await H.save();await H.wait(()=>equal(H.node(F).children.map(n=>n.id),[B,A]));H.assert(H.doc(A).includes('Prima frază'),'Document changed');});
  T('cork-stacked','Corkboard','Selecție de două dosare / panouri stivuite / + Fișă','Fiecare container are propriul titlu; + Fișă adaugă numai în dosarul acelui panou.',async()=>{await H.select(F);await H.row('template-folder').click({modifiers:['Control']});await H.command('viewCorkboard');},async()=>{await H.wait(()=>p().locator('.cork-stacked').count().then(n=>n===2));await p().locator('.cork-stacked').nth(1).getByRole('button',{name:'+ Fișă',exact:true}).click();},async()=>{await H.save();await H.wait(()=>H.node('template-folder').children.length===2);H.assert(H.node(F).children.length===2,'Stack add changed wrong folder');H.assert((await p().locator('.cork-stacked').nth(1).locator('h2').innerText())==='Șabloane verificate','Wrong stacked title');});
  for(const show of [true,false])T('cork-image-'+show,'Corkboard','Fișă / imagine sinopsis '+show,'Imaginea reală din media este afișată sau textarea revine conform preferinței.',async()=>{await H.fixture(async(pj,files)=>{const n=H.flat(pj.tree).find(x=>x.id===A);n.synopsisImage='qa-image.png';n.showSynopsisImage=show;files['media/qa-image.png']=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl6XjIAAAAASUVORK5CYII=','base64');});await view('cork');},async()=>{await visible(card(A));},async()=>{if(show){await H.wait(()=>card(A).locator('img').evaluate(e=>e.complete&&e.naturalWidth===1));H.assert(await card(A).locator('textarea').count()===0,'Image should replace synopsis');}else H.assert(await card(A).locator('textarea').count()===1&&await card(A).locator('img').count()===0,'Hidden image did not restore synopsis');});
  T('cork-decorations','Corkboard','Fișă / etichetă, status, keyword chips','Culoarea etichetei, ștampila status și benzile/chipurile cuvintelor cheie reflectă metadata.',async()=>{await planFixture();await view('cork');},async()=>card(A).focus(),async()=>{H.assert(await card(A).evaluate(e=>e.style.borderTopColor)==='rgb(232, 176, 74)','Wrong label color');H.assert(await card(A).locator('.stamp').innerText()==='De făcut','Wrong stamp');H.assert(await card(A).locator('.chip').innerText()==='fir-a','Wrong keyword');H.assert(await card(A).locator('.card-kw-strip > span').evaluate(e=>e.style.background)==='rgb(255, 0, 0)','Wrong keyword color');});
  // Outliner columns: toggle every base/custom column; all sort headers in both directions.
  for(const [key,label]of columns)for(const on of [true,false])
    T('out-column-'+key+'-'+on,'Outliner','Coloane / '+label+' '+on,'Coloana și preferința localStorage se schimbă; valorile celor două documente rămân accesibile.',startOut,async()=>{await showColumn(key);const choice=outline().locator('.col-list label').filter({hasText:new RegExp('^\\s*'+label+'\\s*$')}).locator('input');await choice.setChecked(on);await outline().locator('summary').click();},async()=>{H.assert(await outline().locator('th').filter({hasText:new RegExp('^\\s*'+label+'\\s*$')}).count()===(on?1:0),'Header visibility wrong');H.assert(await p().evaluate(({key,on})=>JSON.parse(localStorage.getItem('pneuma-outline-columns')).includes(key)===on,{key,on}),'Column selection not persisted');H.assert(await row(A).count()===1&&await row(B).count()===1,'Rows lost');});
  const sortKeys=[['title','Titlu'],...columns];
  const sortValue=(n,key)=>{if(key==='title')return n.title;if(key==='label')return labels.indexOf(n.label);if(key==='status')return statuses.indexOf(n.status);if(key==='include')return n.includeInCompile===false?0:1;if(key==='target')return n.target;if(key==='keywords')return n.keywords.join(', ');if(key==='words'||key==='total')return n.id===A?8:4;if(key==='chars')return n.id===A?41:22;if(key==='progress')return n.id===A?.08:.02;if(key.startsWith('custom:'))return n.custom[key.slice(7)];return n[key]||'';};
